class Solution {
  public boolean isMajorityElement(int[] nums, int target) {
    int first = lowerBound(nums, target);
    // a majority element must also sit at first + n/2
    int mid = first + nums.length / 2;
    return mid < nums.length && nums[mid] == target;
  }

  private int lowerBound(int[] a, int x) {
    int lo = 0, hi = a.length;
    while (lo < hi) {
      int m = (lo + hi) >>> 1;
      if (a[m] < x) lo = m + 1;
      else hi = m;
    }
    return lo;
  }
}
